// Componente de Registro

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-registro',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './registro.component.html',
  styleUrls: ['./registro.component.css'],
})
export class RegistroComponent {
  // Formulario
  email: string = '';
  nombre: string = '';
  fechaNacimiento: string = '';
  password: string = '';
  passwordConfirm: string = '';

  // Estados
  mostrarContrasena: boolean = false;
  mostrarConfirmar: boolean = false;
  cargando: boolean = false;
  error: string = '';
  exito: string = '';

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  // Cambiar visibilidad de contraseña
  cambiarVisibilidad(campo: 'password' | 'confirm'): void {
    if (campo === 'password') {
      this.mostrarContrasena = !this.mostrarContrasena;
    } else {
      this.mostrarConfirmar = !this.mostrarConfirmar;
    }
  }

  // Enviar formulario de registro
  enviar(): void {
    // Validar campos
    if (
      !this.email ||
      !this.nombre ||
      !this.fechaNacimiento ||
      !this.password ||
      !this.passwordConfirm
    ) {
      this.error = 'Por favor completa todos los campos';
      return;
    }

    // Validar que contraseñas coincidan
    if (this.password !== this.passwordConfirm) {
      this.error = 'Las contraseñas no coinciden';
      return;
    }

    this.cargando = true;
    this.error = '';

    this.authService
      .registro({
        email: this.email,
        nombre: this.nombre,
        fechaNacimiento: this.fechaNacimiento,
        password: this.password,
        passwordConfirm: this.passwordConfirm,
      })
      .subscribe({
        next: (response) => {
          if (response.success) {
            // Guardar email para verificación
            sessionStorage.setItem('emailVerificacion', this.email);
            this.exito = response.message;

            // Redirigir a verificación después de 2 segundos
            setTimeout(() => {
              this.router.navigate(['/verificacion']);
            }, 2000);
          } else {
            this.error = response.message;
          }
          this.cargando = false;
        },
        error: (err) => {
          this.error = err.error?.message || 'Error al registrarse';
          this.cargando = false;
        },
      });
  }
}
<!-- Template HTML de Registro -->

<div class="registro-container">
  <!-- Lado izquierdo - Decoración -->
  <div class="registro-decoracion">
    <div class="decoracion-contenido">
      <h1>DevProjects</h1>
      <p>&Uacute;nete a la comunidad de ingenieros de software</p>
    </div>
  </div>

  <!-- Lado derecho - Formulario -->
  <div class="registro-formulario">
    <div class="formulario-contenedor">
      <h2>Crea una cuenta</h2>
      <p>Reg&iacute;strate para comenzar a buscar proyectos</p>

      <!-- Mensaje de error -->
      <div *ngIf="error" class="alert alert-error">
        {{ error }}
      </div>

      <!-- Mensaje de éxito -->
      <!-- Cambiado éxito a exito -->
      <div *ngIf="exito" class="alert alert-success">
        {{ exito }}
      </div>

      <!-- Formulario -->
      <form (ngSubmit)="enviar()" class="formulario">
        <!-- Email -->
        <div class="form-group">
          <label for="email" class="form-label">Correo electr&oacute;nico</label>
          <input
            type="email"
            id="email"
            class="form-input"
            [(ngModel)]="email"
            name="email"
            placeholder="ejemplo@email.com"
          />
        </div>

        <!-- Nombre -->
        <div class="form-group">
          <label for="nombre" class="form-label">Nombre completo</label>
          <input
            type="text"
            id="nombre"
            class="form-input"
            [(ngModel)]="nombre"
            name="nombre"
            placeholder="Tu nombre"
          />
        </div>

        <!-- Fecha de nacimiento -->
        <div class="form-group">
          <label for="fecha" class="form-label">Fecha de nacimiento</label>
          <input
            type="date"
            id="fecha"
            class="form-input"
            [(ngModel)]="fechaNacimiento"
            name="fechaNacimiento"
          />
        </div>

        <!-- Contraseña -->
        <div class="form-group">
          <label for="password" class="form-label">Contrase&ntilde;a</label>
          <div class="input-con-icono">
            <input
              [type]="mostrarContrasena ? 'text' : 'password'"
              id="password"
              class="form-input"
              [(ngModel)]="password"
              name="password"
              placeholder="M&iacute;nimo 8 caracteres"
            />
            <button
              type="button"
              class="btn-icono"
              (click)="cambiarVisibilidad('password')"
            >
              {{ mostrarContrasena ? '&#128065;&#65039;' : '&#128065;&#65039;&#8205;&#128488;&#65039;' }}
            </button>
          </div>
        </div>

        <!-- Confirmar contraseña -->
        <div class="form-group">
          <label for="passwordConfirm" class="form-label">Confirmar contrase&ntilde;a</label>
          <div class="input-con-icono">
            <input
              [type]="mostrarConfirmar ? 'text' : 'password'"
              id="passwordConfirm"
              class="form-input"
              [(ngModel)]="passwordConfirm"
              name="passwordConfirm"
              placeholder="Repite tu contrase&ntilde;a"
            />
            <button
              type="button"
              class="btn-icono"
              (click)="cambiarVisibilidad('confirm')"
            >
              {{ mostrarConfirmar ? '&#128065;&#65039;' : '&#128065;&#65039;&#8205;&#128488;&#65039;' }}
            </button>
          </div>
        </div>

        <!-- Botón -->
        <button
          type="submit"
          class="btn btn-primary btn-bloque"
          [disabled]="cargando"
        >
          {{ cargando ? 'Registrando...' : 'Crear Cuenta' }}
        </button>
      </form>

      <!-- Link a login -->
      <p class="texto-login">
        &iquest;Ya tienes cuenta?
        <a routerLink="/login" class="link-login">Inicia sesi&oacute;n aqu&iacute;</a>
      </p>
    </div>
  </div>
</div>
